func combine_experience(base_xp, bonus_xp):
    return max(0, base_xp + bonus_xp)

func calculate_wave_reward(base_xp, bonus_xp, multiplier):
    return combine_experience(base_xp, bonus_xp) * multiplier

print(calculate_wave_reward(base_xp, bonus_xp, multiplier))
